package org.example;public class Player {    private String name;    private String country;    private int goals;    public String getName() {        return name;    }    public void setName(String name) {        this.name = name;    }    public String getCountry() {        return country;    }    public void setCountry(String country) {        this.country = country;    }    public int getGoals() {        return goals;    }    public void setGoals(int goals) {        this.goals = goals;    }    public Player(String name, String country, int goals) {        this.name = name;        this.country = country;        this.goals = goals;    }    @Override    public String toString() {        return "Player{" +                "name='" + name + '\'' +                ", country='" + country + '\'' +                ", goals=" + goals +                '}';    }}